tables.sql:
CREATE TABLE ab_sample_v1 (
  asset_id TEXT PRIMARY KEY, sample_role TEXT, source_label TEXT,
  capture_time TEXT, media_type TEXT, region TEXT, path TEXT, selected_at TEXT);

CREATE TABLE asset_fingerprint_v01 (
      asset_id TEXT PRIMARY KEY REFERENCES media_asset(asset_id), file_id TEXT NOT NULL REFERENCES media_file(file_id),
      sha256 TEXT, phash TEXT, fingerprint_version TEXT NOT NULL, evidence_json TEXT NOT NULL, created_at TEXT NOT NULL
    );

CREATE TABLE canonical_candidate_v01 (
      group_id TEXT NOT NULL, asset_id TEXT NOT NULL REFERENCES media_asset(asset_id), canonical_score REAL NOT NULL,
      reasons_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('candidate','selected','rejected')) DEFAULT 'candidate',
      created_at TEXT NOT NULL, PRIMARY KEY(group_id,asset_id)
    );

CREATE TABLE crop_v0 (
        asset_id TEXT PRIMARY KEY,
        x REAL NOT NULL, y REAL NOT NULL, w REAL NOT NULL, h REAL NOT NULL,
        updated_at TEXT NOT NULL
    );

CREATE TABLE event_person (
  event_id TEXT NOT NULL REFERENCES event(event_id),
  person_id TEXT NOT NULL REFERENCES person(person_id),
  confidence REAL,
  PRIMARY KEY(event_id,person_id)
);

CREATE TABLE face_embedding_v0 (
      face_instance_id TEXT PRIMARY KEY REFERENCES face_instance_v0(face_instance_id), embedding_model TEXT NOT NULL,
      dimension INTEGER NOT NULL, embedding BLOB, norm REAL, status TEXT NOT NULL CHECK(status IN ('success','failed','skipped')), created_at TEXT NOT NULL);

CREATE TABLE face_unassign_audit_v0 (
  face_instance_id TEXT PRIMARY KEY, person_id TEXT, display_name TEXT,
  capture_time TEXT, birth_date TEXT, reason TEXT, created_at TEXT);

CREATE TABLE face_vlm_attr_v0 (
        face_instance_id TEXT PRIMARY KEY, age_years REAL, age_stage TEXT, gender TEXT,
        raw TEXT, created_at TEXT);

CREATE TABLE family (
  family_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai',
  created_at TEXT NOT NULL
);

CREATE TABLE gold_set_meta (
      gold_set_id TEXT PRIMARY KEY,
      status TEXT NOT NULL DEFAULT 'building',   -- building -> frozen
      frozen_at TEXT,
      notes TEXT
    );

CREATE TABLE group_label_v0 (
        group_key TEXT PRIMARY KEY,
        label TEXT NOT NULL,
        updated_at TEXT NOT NULL
    );

CREATE TABLE group_order_v0 (
        group_key TEXT PRIMARY KEY,
        sort_order INTEGER NOT NULL DEFAULT 0,
        updated_at TEXT NOT NULL
    );

CREATE VIRTUAL TABLE memory_search USING fts5(
            subject_type UNINDEXED, subject_id UNINDEXED, text,
            tokenize='trigram');

CREATE TABLE privacy_pin_v0 (
        id INTEGER PRIMARY KEY CHECK (id=1),
        pin_hash TEXT NOT NULL,
        updated_at TEXT NOT NULL
    );

CREATE TABLE privacy_v0 (
        asset_id TEXT PRIMARY KEY,
        created_at TEXT NOT NULL
    );

CREATE TABLE recycle_v0 (
        asset_id TEXT PRIMARY KEY,
        reason TEXT NOT NULL DEFAULT 'USER',
        created_at TEXT NOT NULL
    );

CREATE TABLE time_assessment (
      asset_id TEXT PRIMARY KEY REFERENCES media_asset(asset_id),
      file_id TEXT NOT NULL REFERENCES media_file(file_id),
      category TEXT NOT NULL, proposed_capture_time TEXT, confidence REAL NOT NULL,
      evidence_json TEXT NOT NULL, flags_json TEXT NOT NULL, assessed_at TEXT NOT NULL
    );
